def _banner_file(banner_name: str):
    data = EMBEDDED_BANNERS.get(banner_name)
    if not data:
        return None
    raw = base64.b64decode("".join(data) if isinstance(data, (list, tuple)) else data)
    return discord.File(io.BytesIO(raw), filename=banner_name)


